/**
 * Deterministic 1999 meet-card opportunity calendar for generated worlds.
 * Derived from the existing local track program, never invented race results.
 * Entries/results are intentionally NOT generated by this planning layer.
 */
import {trackProgram1999,trackMeetOpen1999,trackCardSurface1999}
 from '../../next/1999-track-program.mjs';
export const FICTIONAL_1999_CALENDAR_SCHEMA='WTW_FICTIONAL_1999_RACE_OPPORTUNITIES_V1';
const raceKinds=Object.freeze(['MAIDEN','CLAIMING','ALLOWANCE','HANDICAP','OPEN']);
export function buildFictional1999RaceCalendar(tracks,{racesPerCard=8}={}){
 if(!Array.isArray(tracks)||!Number.isInteger(racesPerCard)||racesPerCard<4||
  racesPerCard>14)throw Error('Invalid 1999 racing calendar settings');
 const cards=[],unprogrammed=[];
 const start=Date.UTC(1999,0,1),day=86400000;
 for(const track of tracks){
  if(track.playableIn1999===false||track.trackOperating==='HISTORICAL_ONLY'||
   track.operating==='HISTORICAL_ONLY'||track.status==='HISTORICAL_ONLY')continue;
  const program=trackProgram1999(track.id);
  if(!program){unprogrammed.push(track.id);continue}
  for(let d=0;d<365;d++){
   const date=new Date(start+d*day).toISOString().slice(0,10);
   if(!trackMeetOpen1999(track.id,date))continue;
   const races=Array.from({length:racesPerCard},(_,i)=>({
    id:'R-1999-'+track.id+'-'+date+'-'+String(i+1).padStart(2,'0'),
    raceNumber:i+1,condition:raceKinds[i%raceKinds.length],
    surface:trackCardSurface1999(track.id,i),status:'SCHEDULED',
    fieldHorseIds:[],winnerId:null,purse_minor:null
   }));
   cards.push({id:'CARD-'+track.id+'-'+date,trackId:track.id,date,
    basis:program.basis??'WTW_GAME_MODELED',races});
  }
 }
 cards.sort((a,b)=>a.date.localeCompare(b.date)||a.trackId.localeCompare(b.trackId));
 return {schema:FICTIONAL_1999_CALENDAR_SCHEMA,year:1999,cards,
  unprogrammedTrackIds:unprogrammed,
  summary:{raceDays:cards.length,scheduledRaces:cards.length*racesPerCard,
   tracksWithCards:new Set(cards.map(c=>c.trackId)).size}};
}
